import { ref } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
export default {
  __name: 'DeleteNetworkDialog',
  setup(__props, {
    expose: __expose
  }) {
    const visible = ref(false);
    const form = ref({
      networkName: ''
    });
    const networkNames = ref([]);
    const fetchNetworkNames = async () => {
      try {
        const res = await axios.get('http://localhost:8081/network/list');
        networkNames.value = Object.keys(res.data);
      } catch (err) {
        ElMessage.error('获取网络列表失败');
      }
    };
    const openDialog = () => {
      form.value.networkName = '';
      visible.value = true;
      fetchNetworkNames();
    };
    const closeDialog = () => {
      visible.value = false;
      form.value.networkName = '';
    };
    const submitDelete = async () => {
      if (!form.value.networkName) {
        ElMessage.warning('请选择网络名称');
        return;
      }
      try {
        await axios.delete(`http://localhost:8081/network/delete/${form.value.networkName}`);
        ElMessage.success('删除成功');
        // 删除成功后刷新网络列表
        await fetchNetworkNames();
        form.value.networkName = '';
      } catch (err) {
        ElMessage.error('删除失败');
      }
    };

    // 暴露给父组件打开弹窗
    __expose({
      openDialog
    });
    const __returned__ = {
      visible,
      form,
      networkNames,
      fetchNetworkNames,
      openDialog,
      closeDialog,
      submitDelete,
      ref,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
